{
  "sql": "SELECT r.return_id, r.order_id, r.product_id, r.return_date, r.return_quantity, r.refund_amount, r.return_reason, p.category FROM commerce.returns AS r INNER JOIN commerce.products AS p ON r.product_id = p.product_id WHERE r.return_date >= $1 AND r.return_date < $2 ORDER BY 1 LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Retrieves return records from 2022 by filtering return_date within the year range, joining with products to include category, and limiting to 200 rows."
}
